import {CITIES,SUSPECTS,TERMS,newCase,clueFor,culpritOf,validSave} from './engine.js';
const app=document.querySelector('#app'),book=document.querySelector('#book'),storageKey='mma-baroque-case-v1';
let state=null,screen='home',feedback='',feedbackGood=false,bookTab='guide',saveAvailable=true;
try{const v=JSON.parse(localStorage.getItem(storageKey));if(validSave(v))state=v;}catch{}
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(type,cl='')=>{const paths={book:'M4 4h7c2 0 3 1 3 2v15c0-2-2-3-4-3H4z M24 4h-7c-2 0-3 1-3 2v15c0-2 2-3 4-3h6z',search:'M18 18l7 7 M21 12A9 9 0 1 1 3 12a9 9 0 0 1 18 0',arrow:'M5 14h18 M17 7l7 7-7 7',check:'M4 15l6 6L24 6',pin:'M14 26S5 17 5 11a9 9 0 1 1 18 0c0 6-9 15-9 15z M17 11a3 3 0 1 1-6 0 3 3 0 0 1 6 0',music:'M11 22V6l12-3v16 M11 5v5l12-3 M11 22c0 3-7 5-7 1s7-4 7-1 M23 19c0 3-7 5-7 1s7-4 7-1',seal:'M14 2l4 3 5 1 1 5 2 4-3 4-1 5-5 1-4 2-4-3-5-1-1-5-2-4 3-4 1-5 5-1z',close:'M6 6l16 16 M22 6L6 22'};return `<svg class="icon ${cl}" viewBox="0 0 28 28" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[type]||paths.music}"/></svg>`;};
const button=(text,action,cls='primary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const city=()=>CITIES[state.route[state.chapter]];
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));saveAvailable=true;}catch{saveAvailable=false;}}
function notify(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('visible'),4200);}
function header(){return `<header class="topbar"><button class="brand" data-action="home" aria-label="Return to agency desk"><span class="brand-seal">${icon('music')}</span><span>Musical Mystery<span class="brand-bottom">A G E N C Y</span></span></button><div class="header-right">${screen==='game'&&state?`<span class="case-id">${state.caseCode} <span>·</span> 1735</span>`:`<span class="prototype-tag">A playable sample case</span>`}${button(`${icon('book')} <span>Casebook</span>`,'book','book-button')}</div></header>`;}
function professor(text,small=false){return `<div class="professor ${small?'small':''}"><div class="professor-portrait"><img src="assets/professor.webp" alt="Your Agency guide, a goggled professor in a lab coat with a brown beard" onerror="this.parentElement.classList.add('portrait-fallback');this.style.display='none'"></div><div><span class="eyebrow">Your Agency guide</span><p>${text}</p></div></div>`;}
function renderHome(){const eras=[['Medieval','c. 500–1400','I'],['Renaissance','c. 1400–1600','II'],['Baroque','c. 1600–1750','III'],['Classical','c. 1750–1820','IV'],['Romantic','c. 1820–1900','V'],['Impressionistic','c. 1890–1920','VI']];app.innerHTML=`<div class="shell home-shell">${header()}<main class="home-stage"><div class="home-backdrop"></div><div class="home-shade"></div><div class="hero-content"><span class="eyebrow gold">THE ARCHIVES ARE OPEN</span><h1>Every era has<br>its <em>secrets.</em></h1><p class="hero-copy">A stolen score. A trail through time.<br>Let the music lead you to the truth.</p><div class="hero-actions">${state?button(`${state.solved?'View solved case':'Continue your case'} ${icon('arrow')}`,'continue'):button(`Open the Baroque case ${icon('arrow')}`,'new')}${state?button(state.solved?'Play a new case':'Start a fresh case','new','text-button'):''}</div><p class="play-note">Read the clues. Learn in your casebook. Catch the thief.<br>No sound needed · No countdown · Take your time</p></div><div class="hero-professor">${professor('“Welcome, detective. Someone has stolen the Moonlight Folio. I could use a sharp mind like yours.”')}</div><div class="era-shelf"><div class="shelf-heading"><span class="eyebrow">Choose your musical era</span><span class="tiny">One case available in this prototype</span></div><div class="eras">${eras.map(([name,date,n])=>`<button class="era ${name==='Baroque'?'available':'upcoming'}" data-action="${name==='Baroque'?'new':'upcoming'}" ${name==='Baroque'?'':'aria-disabled="true"'}><span class="era-number">${n}</span><span class="era-name">${name}</span><span class="era-date">${date}</span><span class="era-status">${name==='Baroque'?'Open case →':'Upcoming'}</span></button>`).join('')}</div></div></main><footer class="fineprint">Fictional mystery, real musical history. Period dates are approximate and overlapping.</footer></div>`;}
function startNew(){if(state&&!state.solved&&screen!=='briefing'){showRestart();return;}doNew();}
function doNew(){const a=new Uint32Array(1);crypto.getRandomValues(a);state=newCase(a[0]);screen='game';feedback='';save();render();}
function showRestart(){bookTab='restart';book.innerHTML=`<div class="dialog-head"><h2 id="book-title">Begin a fresh investigation?</h2>${button(icon('close'),'close','icon-button','aria-label="Close"')}</div><div class="dialog-content"><p>A fresh case changes the route, culprit, and clues. It will replace your saved case on this device.</p><div class="dialog-actions">${button('Keep my current case','close','secondary')}${button('Start a fresh case','confirm-new')}</div></div>`;book.showModal();}
function renderBriefing(){const first=CITIES[state.route[0]];return `<main class="briefing-stage" style="--scene:url('assets/${first.image}')"><article class="briefing-paper"><div class="file-label">CONFIDENTIAL · CASE 001</div><div class="folio-symbol">${icon('music')}</div><span class="eyebrow">Baroque Europe · 1735</span><h1>The Stolen<br><em>Moonlight Folio</em></h1><p>A rare collection of copied music has disappeared. A travelling thief is passing it off as their own, and three cities hold the trail.</p><div class="mission-list"><div><b>01</b><span>Question witnesses and read the music clues.</span></div><div><b>02</b><span>Use your casebook to make connections.</span></div><div><b>03</b><span>Follow the route, then identify the thief.</span></div></div>${professor('“The folio is still out there. Be thorough, not hurried. Every answer you need can be found in your casebook.”',true)}${button(`Begin in ${first.name} ${icon('arrow')}`,'begin')}<p class="tiny centered">Your progress saves on this device. All suspects and the stolen folio are fictional.</p></article></main>`;}
function scene(){const c=city();return `<section class="scene" style="--scene:url('assets/${c.image}')" aria-label="Illustrated ${c.name} in 1735"><div class="scene-vignette"></div><div class="location-plaque"><span class="eyebrow">${c.country} · 1735</span><h1>${c.name}</h1><p>${c.place}</p></div><div class="scene-chapter">STOP ${state.chapter+1} OF 3</div><div class="scene-bottom"><div class="scene-quote"><span class="small-diamond">✦</span><p>${c.intro}</p></div><div class="evidence-strip">${state.evidence.length?state.evidence.map((e,i)=>`<button class="evidence-token" data-action="evidence" aria-label="Read clue ${i+1}: ${safe(e.text)}"><span>${icon(e.kind==='seal'?'seal':e.kind==='accessory'?'search':'music')}</span><small>CLUE ${i+1}</small></button>`).join(''):`<span class="quiet-note">Your evidence will collect here.</span>`}<button class="scene-book" data-action="book" aria-label="Consult your casebook">${icon('book')}<span>Consult your<br><b>casebook</b></span></button></div></div></section>`;}
function stepTrail(){return `<nav class="trail" aria-label="Investigation progress">${state.route.map((id,i)=>`<span class="trail-stop ${i===state.chapter?'current':i<state.chapter?'done':''}"><span class="stop-dot">${i<state.chapter?'✓':i+1}</span>${i<=state.chapter?CITIES[id].name:'Next destination'}</span>${i<2?'<span class="trail-line"></span>':''}`).join('')}<span class="trail-goal">Recover the folio</span></nav>`;}
function feedbackBlock(){return feedback?`<div class="feedback ${feedbackGood?'good':''}" role="status">${feedbackGood?icon('check'):icon('book')}<span>${feedback}</span></div>`:'';}
function questionPanel(){const c=city();const opts=state.optionOrders[state.route[state.chapter]].map(id=>c.options.find(o=>o.id===id));return `<span class="eyebrow">Make the musical connection</span><h2>${c.artifact}</h2><div class="manuscript"><div class="staff">𝄞 <span>♪ ♩ ♫ ♩ ♪</span></div><span>${c.artifactSub}</span></div><p class="question">${c.challenge}</p><div class="answers">${opts.map((o,i)=>button(`<span class="answer-letter">${String.fromCharCode(65+i)}</span><span>${o.label}</span>`,'answer','answer',`data-value="${o.id}"`)).join('')}</div>${feedbackBlock()}${button(`${icon('book')} Find the explanation in my casebook`,'book','hint-link')}`;}
function investigatePanel(){const c=city();return `<span class="eyebrow">Investigate the lead</span><h2>A witness remembers.</h2><p>${state.witnessRead?'Read the witness’s words, then examine the music clue.':'Speak to the local witness. Their account will help you understand the missing music.'}</p><div class="witness-card"><span class="witness-avatar">${icon('music')}</span><div><b>${c.person}</b><span>Witness · ${c.name}</span></div></div>${state.witnessRead?`<blockquote class="testimony">${c.witness}</blockquote>${button(`Examine the music clue ${icon('arrow')}`,'examine')}`:button(`Interview ${c.person.split(',')[0]} ${icon('arrow')}`,'interview')}<div class="guide-small">${professor('“You do not need to know the answer already. Open your casebook whenever you need it.”',true)}</div>`;}
function routePanel(){const c=city(),next=CITIES[state.route[state.chapter+1]],clue=state.evidence[state.chapter];return `<span class="eyebrow">A clue secured</span><h2>The trail continues.</h2><div class="music-confirm">${icon('check')}<span><b>${TERMS.find(t=>t.id===c.term).name} identified</b>${c.explanation}</span></div><div class="clue-note"><span class="eyebrow">Witness identification</span><p>“${clue.text}”</p><span class="tiny">Added to your evidence</span></div><h3>Where did the thief go next?</h3><blockquote class="route-clue">${next.routeClue}</blockquote><div class="city-options">${Object.keys(CITIES).map(id=>button(`${icon('pin')} ${CITIES[id].name}`,'travel','city-option',`data-value="${id}"`)).join('')}</div>${feedbackBlock()}`;}
function portrait(s){return `<svg class="suspect-portrait" viewBox="0 0 180 155" role="img" aria-label="Illustrated portrait of ${s.name}"><defs><linearGradient id="bg-${s.id}" x2="0" y2="1"><stop stop-color="#385253"/><stop offset="1" stop-color="#13282c"/></linearGradient></defs><rect width="180" height="155" fill="url(#bg-${s.id})"/><circle cx="90" cy="64" r="47" fill="#d5b976" opacity=".08"/><path d="M35 155q2-51 55-53 53 2 55 53" fill="${s.color}"/><path d="M75 98l15 41 15-41" fill="#eee0c1"/><path d="M62 107l15-9 13 42-29-20 10-4z M118 107l-15-9-13 42 29-20-10-4z" fill="#b69966"/><rect x="81" y="83" width="18" height="26" rx="8" fill="${s.skin}"/><ellipse cx="90" cy="65" rx="27" ry="35" fill="${s.skin}"/><path d="M62 62q-10-39 26-41 35-1 31 44l-9-15-9-13-12 9-23-1z" fill="${s.hair}"/><path d="M80 70h1 M99 70h1" stroke="#332921" stroke-width="4" stroke-linecap="round"/><path d="M85 85q6 4 12-1" stroke="#8c513d" stroke-width="2" fill="none"/>${s.accessory==='amber spectacles'?'<g fill="none" stroke="#ce9d46" stroke-width="2.5"><circle cx="79" cy="68" r="10"/><circle cx="101" cy="68" r="10"/><path d="M89 67h3 M69 66l-7-3 M111 66l7-3"/></g>':'<path d="M110 40l15-3-5 11 8 8-17-2z" fill="#5190bd"/>'}<path d="M86 106h8l-2 7 5 13-7 9-7-9 5-13z" fill="#8d4938"/><circle cx="121" cy="125" r="7" fill="#bd9959"/><text x="121" y="129" font-size="11" text-anchor="middle" fill="#392e1c">${s.seal==='a raven'?'R':'F'}</text></svg>`;}
function suspects(selectable=false){return `<div class="suspects-grid">${state.suspectOrder.map(id=>{const s=SUSPECTS.find(s=>s.id===id);return `<${selectable?'button':'article'} class="suspect-card" ${selectable?`data-action="accuse" data-value="${s.id}"`:''}>${portrait(s)}<div class="suspect-copy"><h3>${s.name}</h3><span class="suspect-job">${s.job}</span><p>${s.accessory}<br>Seal: ${s.seal}<br>${s.mark}</p>${selectable?'<span class="suspect-select">Identify suspect →</span>':''}</div></${selectable?'button':'article'}>`;}).join('')}</div>`;}
function finale(){let culprit=culpritOf(state);return `<main class="finale-stage" style="--scene:url('assets/${city().image}')"><div class="finale-paper"><span class="eyebrow">The final deduction</span><h1>${state.finaleStage==='lock'?'One last musical key.':'Who carried the stolen folio?'}</h1>${state.finaleStage==='lock'?`<p>Your evidence identifies <b>${culprit.name}</b>. The folio is recovered inside a locked music case. Its clasp carries one final riddle.</p><div class="lock-riddle"><span class="eyebrow">The case’s musical lock</span><p>“A cello carries the bass line.<br>A harpsichord supplies the chords.<br>Together, we support the music.”</p><h2>What is this musical foundation called?</h2></div><div class="lock-answers">${['opera','continuo','concerto'].map(id=>button(TERMS.find(t=>t.id===id).name,'unlock','answer',`data-value="${id}"`)).join('')}</div>${feedbackBlock()}${button(`${icon('book')} Consult the field guide`,'book','hint-link')}`:`<p>Compare <b>all three clues</b> with the four fictional suspects. One person matches every detail.</p><div class="final-evidence">${state.evidence.map((e,i)=>`<div><span>0${i+1} · ${CITIES[e.city].name}</span><p>${e.text}</p></div>`).join('')}</div>${suspects(true)}${feedbackBlock()}`}<p class="tiny centered">An incorrect deduction is a chance to recheck your evidence. You can try again.</p></div></main>`;}
function solved(){const p=culpritOf(state);return `<main class="solved-stage" style="--scene:url('assets/${city().image}')"><article class="solved-card" id="solved-card"><div class="solved-ribbon">MUSICAL MYSTERY AGENCY</div><div class="victory-seal">${icon('check')}</div><span class="eyebrow">Baroque Europe · 1735</span><h1>Case <em>solved.</em></h1><h2>The Moonlight Folio is safe.</h2><p>You followed the music across Europe, identified <b>${p.name}</b>, and opened the case with your knowledge of <b>basso continuo</b>.</p><div class="solved-route">${state.route.map(id=>`<span>${CITIES[id].name}</span>`).join('<i>→</i>')}</div><div class="solved-learnings"><span>Concerto</span><span>Cantata</span><span>Opera</span><span>Basso continuo</span></div><p class="case-stamp">FOLIO RECOVERED · INVESTIGATION CLOSED</p><span class="tiny">${state.caseCode}</span><div class="solved-actions">${button('Save case-solved card','save-card')}${button('Play a new case','new','secondary')}</div><p class="tiny centered">You can also take a screenshot of this screen. There is no score.</p></article></main>`;}
function render(){if(screen==='home'){renderHome();return;}let content=state.solved?solved():state.phase==='briefing'?renderBriefing():state.phase==='finale'?finale():`${stepTrail()}<main class="investigation">${scene()}<aside class="case-panel">${state.phase==='investigate'?investigatePanel():state.phase==='question'?questionPanel():routePanel()}</aside></main><div class="bottom-status"><span>${icon('seal')} The folio’s trail is still warm. Take the time you need.</span><span>${saveAvailable?'Progress saved on this device':'Browser storage unavailable; keep this tab open'}</span></div>`;app.innerHTML=`<div class="shell game-shell">${header()}${content}</div>`;}
function showBook(tab='guide'){bookTab=tab;renderBook();if(!book.open)book.showModal();}
function renderBook(){book.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">Musical Mystery Agency</span><h2 id="book-title">The detective’s casebook</h2></div>${button(icon('close'),'close','icon-button','aria-label="Close casebook"')}</div><div class="book-tabs" role="tablist" aria-label="Casebook sections">${[['guide','Field guide'],['evidence','Evidence'],['suspects','Suspects'],['history','Historical notes']].map(([id,t])=>button(t,'book-tab',bookTab===id?'active':'',`role="tab" aria-selected="${bookTab===id}" data-value="${id}"`)).join('')}</div><div class="dialog-content"><div role="tabpanel">${bookTab==='guide'?`<p class="book-intro">Keep this guide beside your investigation. Every musical answer in this case is here.</p><div class="terms-grid">${TERMS.map(t=>`<article class="term"><span class="eyebrow">${t.city}</span><h3>${t.name}</h3><p>${t.text}</p><div class="remember">${t.remember}</div></article>`).join('')}</div><div class="era-note"><b>What makes it Baroque?</b> Roughly 1600–1750, European composers explored dramatic contrast, ornament, musical patterns, and rich bass-supported harmony. Not every piece uses every feature.</div>`:bookTab==='evidence'?state?.evidence.length?`<p class="book-intro">Use these details together to identify the visitor.</p><div class="notebook-evidence">${state.evidence.map((e,i)=>`<article><span class="evidence-number">0${i+1}</span><div><span class="eyebrow">Witness in ${CITIES[e.city].name}</span><h3>${e.text}</h3></div></article>`).join('')}</div>`:'<div class="empty-book">No clues collected yet.<br>Interview witnesses and solve the musical clues to build your case.</div>':bookTab==='suspects'?state?`<p class="book-intro">These four people are fictional. Compare the witness descriptions with their profiles.</p>${suspects()}`:'<div class="empty-book">Open a case to see the suspect files.</div>':`<h3>Real places. An invented investigation.</h3><p>The Moonlight Folio, the professor, witnesses, and suspects are fictional. The journey compresses travel that would have taken much longer in 1735. Illustrations evoke the period rather than reconstructing an exact street view.</p>${Object.values(CITIES).map(c=>`<article class="history-item"><h3>${c.name} · 1735</h3><p>${c.fact}</p></article>`).join('')}<h3>A useful caution</h3><p>Musical forms were not exclusive to one city. The city clues in this case include named people or places, rather than implying that only Venice had concertos, only Leipzig had cantatas, or only London had opera.</p><p class="tiny">Further reading: <a href="https://www.bach-digital.de/" target="_blank" rel="noopener">Bach Digital</a> · <a href="https://handelhendrix.org/learn/about-handel/" target="_blank" rel="noopener">Handel Hendrix House</a> · <a href="https://www.britannica.com/art/Baroque-music" target="_blank" rel="noopener">Baroque music overview</a></p>`}</div></div>`;}
function answer(value){const c=city();if(value!==c.term){feedbackGood=false;feedback='Not quite. Compare the role of singers, instruments, and the stage. Your casebook has the explanation. Try again.';render();return;}feedback='';state.learned.push(c.term);state.evidence.push(clueFor(state));state.phase=state.chapter===2?'finale':'route';save();render();notify('Musical connection made. A witness clue was added to your casebook.');}
function travel(value){const expected=state.route[state.chapter+1];if(value!==expected){feedbackGood=false;feedback='That city does not match the onward address. Re-read its named composer and place, then try again.';render();return;}state.chapter++;state.phase='investigate';state.witnessRead=false;feedback='';save();render();}
function accuse(value){if(value!==state.culprit){feedbackGood=false;feedback='That profile does not match every clue. Look for the person whose accessory, seal, and clasp all match.';render();return;}state.finaleStage='lock';feedback='';save();render();}
function unlock(value){if(value!=='continuo'){feedbackGood=false;feedback='Look for the term that means a bass line plus chordal support. You can revisit the field guide and try again.';render();return;}state.solved=true;state.phase='solved';state.learned.push('continuo');state.completedAt=new Date().toISOString();feedback='';save();render();}
function saveCard(){const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1200;const ctx=canvas.getContext('2d');ctx.fillStyle='#122d31';ctx.fillRect(0,0,1600,1200);ctx.strokeStyle='#cfaf72';ctx.lineWidth=4;ctx.strokeRect(38,38,1524,1124);ctx.strokeRect(54,54,1492,1092);ctx.textAlign='center';ctx.fillStyle='#e9ce97';ctx.font='24px Georgia';ctx.fillText('M U S I C A L   M Y S T E R Y   A G E N C Y',800,135);ctx.font='28px Georgia';ctx.fillText('BAROQUE EUROPE · 1735',800,245);ctx.fillStyle='#fff1d5';ctx.font='italic 116px Georgia';ctx.fillText('Case solved.',800,420);ctx.font='42px Georgia';ctx.fillText('The Moonlight Folio is safe.',800,535);ctx.font='30px Georgia';ctx.fillText(`${culpritOf(state).name} identified. The stolen folio recovered.`,800,635);ctx.fillStyle='#e9ce97';ctx.font='30px Georgia';ctx.fillText(state.route.map(id=>CITIES[id].name).join('  →  '),800,750);ctx.font='26px Georgia';ctx.fillText('Concerto · Cantata · Opera · Basso continuo',800,835);ctx.font='22px Georgia';ctx.fillText('FOLIO RECOVERED · INVESTIGATION CLOSED',800,980);ctx.font='20px Georgia';ctx.fillText(state.caseCode,800,1040);canvas.toBlob(blob=>{if(!blob){notify('Please take a screenshot of your solved-case screen instead.');return;}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`musical-mystery-${state.caseCode}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),30000);notify('Your case-solved card is ready to save.');},'image/png');}
function act(action,value){switch(action){case'home':screen='home';feedback='';render();break;case'new':startNew();break;case'confirm-new':book.close();doNew();break;case'continue':screen='game';feedback='';render();break;case'begin':state.phase='investigate';save();render();break;case'book':showBook();break;case'evidence':showBook('evidence');break;case'close':book.close();break;case'book-tab':bookTab=value;renderBook();break;case'upcoming':notify('This era is planned. The Baroque sample case is ready to play.');break;case'interview':state.witnessRead=true;save();render();break;case'examine':state.phase='question';feedback='';save();render();break;case'answer':answer(value);break;case'travel':travel(value);break;case'accuse':accuse(value);break;case'unlock':unlock(value);break;case'save-card':saveCard();break;}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)act(b.dataset.action,b.dataset.value);});
book.addEventListener('click',e=>{if(e.target===book){const r=book.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)book.close();}});
render();
